def test_gen_contract_files_exist():
    """物化产物必须齐套: 缺任何一个契约文件即判失败 (不留静默缺口)。

    目录整个不存在算 skip 而缺文件算失败: 前者是"还没物化"的合法中间态,
    后者是物化过之后又掉了文件 —— 后者若也 skip, 契约就会在磁盘消失后
    继续显示全绿。
    """
    if not CONTRACTS_DIR.is_dir():                                                                  # 目录不存在算合法中间态, 缺文件才是回归
        # 尚未物化不是回归: 显式 skip。**BC-20**: 原文写的是
        # 「先运行 scripts/refactor/materialize_contracts.py」—— 那条路**不存在**:
        # 全仓既没有 scripts/ 目录, 也没有任何 materialize 脚本 (已用
        # `git log --diff-filter=D` 与全仓文件普查确认)。让人去跑一个不存在的文件,
        # 等于给一条死路, 排查的人会以为契约丢了却找不到重建入口。
        # 真实恢复路径是从版本控制取回 —— 契约是入库资产, 不是构建产物。
        pytest.skip("contracts/ 尚未物化 (从版本控制取回: `git checkout -- contracts/`)")
    missing = [f for f in EXPECTED_FILES if not (CONTRACTS_DIR / f).is_file()]  # 全集比对: 少一个都点名
    assert missing == [], f"缺少契约文件: {missing}"  # 物化后掉文件 = 真实回归, 不能并入上面的 skip


def test_gen_input_contract_structure():
    """input.contract.yaml 的头字段与 input 侧每个字段的 type/unit/required 必须与 spec 一致。"""
    if not (CONTRACTS_DIR / "input.contract.yaml").is_file():
        pytest.skip("input.contract.yaml 尚未物化")                                                  # 单文件缺失按未物化处理, 不与上面那条例外混谈
    data = yaml.safe_load((CONTRACTS_DIR / "input.contract.yaml").read_text(encoding="utf-8"))
    assert data["skill"] == SKILL  # 三件套: 归属/方向/schema 名, 任一漂移即跨 skill 失配
    assert data["kind"] == "input"
    assert data["schema"] == INPUT_SCHEMA                                                          # schema 名必须与 spec 逐字相等
    for fname, fmeta in FIELDS_FILES["input"].items():
        assert fname in data["fields"]  # 字段必须逐个登记, 少一个下游就取不到
        f = data["fields"][fname]                                                                   # 取出该字段的契约段
        assert f["type"] == fmeta["type"] and f["unit"] == fmeta["unit"]  # type/unit 派生自 spec, 不得私改
        assert f["required"] is True  # 身份类输入缺了整条链就跑不通


def test_gen_output_contract_structure():
    """output.contract.yaml 的 gates 必须与 spec 逐条相等 (门禁阈值不得在契约里漂移)。"""
    if not (CONTRACTS_DIR / "output.contract.yaml").is_file():                                      # 输出契约同样先判文件在不在
        pytest.skip("output.contract.yaml 尚未物化")
    data = yaml.safe_load((CONTRACTS_DIR / "output.contract.yaml").read_text(encoding="utf-8"))
    assert data["skill"] == SKILL
    assert data["kind"] == "output"
    assert data["schema"] == OUTPUT_SCHEMA
    for fname, _fmeta in FIELDS_FILES["output"].items():  # 输出侧只查登记, 字段内容在 test_gen_fields 逐项守
        assert fname in data["fields"]
    spec = get_spec_data()                                                                          # 取 spec 切片: 门禁阈值的权威来源
    spec_gates = {g["name"]: (g["cmp"], g["value"]) for g in spec["skills"][SKILL]["gates"]}        # 按门禁名索引, 只取比较符与阈值两元组
    file_gates = {g["name"]: (g["cmp"], g["value"]) for g in data["gates"]}                        # 契约侧同样按名索引成两元组, 才谈得上相等
    assert file_gates == spec_gates  # 阈值在契约里漂移 = 消费方按另一套标准验收
